// wideAssertQuadZeroOnError asserts Quad returns the zero string, int and bool alongside any error.
func wideAssertQuadZeroOnError(
	tb testing.TB,
	w Wide,
	fx WideFixture,
) {
	tb.Helper()
	ctx, cancel := context.WithCancel(tb.Context())
	cancel()
	got, got2, got3, err := w.Quad(ctx, fx.ID())
	if err == nil {
		tb.Skip("Quad answered for a cancelled context, so this check has no error to inspect")
	}

	var zero string
	if got != zero {
		tb.Errorf("Quad must return the zero string alongside an error: got %+v, want %+v (err %v)",
			got, zero, err)
	}
	var zero2 int
	if got2 != zero2 {
		tb.Errorf("Quad must return the zero int alongside an error: got %+v, want %+v (err %v)",
			got2, zero2, err)
	}
	var zero3 bool
	if got3 != zero3 {
		tb.Errorf("Quad must return the zero bool alongside an error: got %+v, want %+v (err %v)",
			got3, zero3, err)
	}
}

